CREATE OR REPLACE FUNCTION private.ensure_profile_handle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  base_handle text;
begin
  if new.handle is null or btrim(new.handle)='' then
    base_handle := trim(both '-' from regexp_replace(lower(new.display_name), '[^a-z0-9]+', '-', 'g'));
    if length(base_handle) < 3 then base_handle := 'member'; end if;
    new.handle := left(base_handle,24) || '-' || substr(replace(new.id::text,'-',''),1,6);
  else
    new.handle := lower(btrim(new.handle));
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.protect_profile_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  request_role text:=(select auth.jwt()->>'role');
begin
  if new.role is distinct from old.role then
    if old.role='buyer'::public.user_role
       and new.role='seller'::public.user_role
       and old.id=(select auth.uid())
       and new.id=old.id then
      return new;
    end if;

    if request_role='service_role' or private.is_admin() then
      return new;
    end if;

    raise exception 'Only administrators can change account roles';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = pg_catalog.now();
  return new;
end;
$function$
